// Turns the hg_settings rows (key/value) into one config object for this run.
const cfg = {};
for (const item of $input.all()) {
  if (item.json && item.json.key) cfg[item.json.key] = item.json.value;
}
if (!cfg.openai_model) throw new Error('hg_settings is empty: run supabase/schema.sql and scripts/setup.py supabase');
cfg.today = new Date().toISOString().slice(0, 10);
return [{ json: cfg }];

// Builds the OpenAI request that turns a call transcript into a structured job description.
// Also handles "request changes": if role_id + feedback are sent, the previous JD is revised.
const body = $('Webhook').first().json.body || {};
const cfg = $('Config').first().json;
const old = $('Load Role').all().map(i => i.json).filter(r => r && r.id)[0] || null;

const transcript = String(body.transcript || (old && old.transcript) || '').trim();
const requestedBy = body.requested_by || 'portal';
if (transcript.length < 200) {
  return [{ json: { error: 'Transcript too short (' + transcript.length + ' characters). Paste the full call notes.', requested_by: requestedBy } }];
}

const list = { type: 'array', items: { type: 'string' } };
const schema = {
  type: 'object', additionalProperties: false,
  required: ['title', 'client_summary_public', 'about_the_role', 'must_haves', 'nice_to_haves', 'responsibilities',
    'languages', 'hours', 'employment_type', 'rate_band', 'start_date', 'reports_to', 'interview_process',
    'internal_notes', 'open_questions', 'search_query'],
  properties: {
    title: { type: 'string' },
    client_summary_public: { type: 'string', description: 'Anonymised one-liner about the client, no company name' },
    about_the_role: { type: 'string', description: '3-4 sentence pitch for candidates' },
    must_haves: list, nice_to_haves: list, responsibilities: list, languages: list,
    hours: { type: 'string' }, employment_type: { type: 'string' }, rate_band: { type: 'string' },
    start_date: { type: 'string' }, reports_to: { type: 'string' }, interview_process: { type: 'string' },
    internal_notes: Object.assign({ description: 'Things the recruiter must know but candidates/client-facing JD must NOT show' }, list),
    open_questions: Object.assign({ description: 'Missing or contradictory info the recruiter should confirm with the client' }, list),
    search_query: { type: 'string', description: 'One plain-English candidate search, e.g. "3+ years GoHighLevel, Zapier or Make, webhooks; Arabic preferred"' }
  }
};

const system = [
  'You are a senior recruiter at a remote-staffing agency that places people with US clients.',
  'Write a clear, honest job description from the client call transcript.',
  'Rules:',
  '- Use ONLY facts stated in the transcript. If something is not stated, write "Not specified" and add it to open_questions.',
  '- Must-haves = things the client called required/non-negotiable/minimum. Nice-to-haves = preferred/plus/bonus.',
  '- Put numbers in requirements exactly as said (e.g. "3+ years of GoHighLevel").',
  '- If the client changed their mind during the call, use the final answer and note the change in internal_notes.',
  '- Never show private remarks (e.g. "don\'t tell them we can pay more") in candidate-facing fields; put them in internal_notes.',
  '- client_summary_public must not contain the client company name.',
  '- Plain, friendly English. No buzzwords.'
].join('\n');

let user = 'Client (internal name): ' + (body.client_name || (old && old.client_name) || 'unknown') +
  '\n\nCALL TRANSCRIPT:\n"""\n' + transcript.slice(0, 30000) + '\n"""';
if (old && body.feedback) {
  user += '\n\nPREVIOUS JD (version ' + old.version + '):\n' + (old.jd_markdown || '') +
    '\n\nRECRUITER FEEDBACK (apply it exactly, keep everything else):\n' + body.feedback;
}

return [{
  json: {
    role_id: old ? old.id : null,
    client_name: body.client_name || (old && old.client_name) || null,
    client_email: body.client_email || (old && old.client_email) || null,
    transcript: transcript,
    requested_by: requestedBy,
    openai_body: {
      model: cfg.openai_model,
      temperature: 0.2,
      response_format: { type: 'json_schema', json_schema: { name: 'job_description', strict: true, schema: schema } },
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }]
    }
  }
}];

// Parses the JD from OpenAI and builds the public markdown + the payload for hg_role_save.
const req = $('Build JD Prompt').first().json;
const res = $input.first().json;
let jd;
try {
  jd = JSON.parse(res.choices[0].message.content);
} catch (e) {
  throw new Error('OpenAI did not return a valid JD: ' + JSON.stringify(res).slice(0, 300));
}

const bullets = arr => (arr || []).map(x => '- ' + x).join('\n') || '- Not specified';
const md = [
  '# ' + jd.title,
  '_' + jd.client_summary_public + '_',
  '',
  '## About the role', jd.about_the_role, '',
  '## Must-haves', bullets(jd.must_haves), '',
  '## Nice-to-haves', bullets(jd.nice_to_haves), '',
  '## What you will do', bullets(jd.responsibilities), '',
  '## Languages', bullets(jd.languages), '',
  '## Details',
  '- Hours: ' + jd.hours,
  '- Type: ' + jd.employment_type,
  '- Pay: ' + jd.rate_band,
  '- Start: ' + jd.start_date,
  '- Reports to: ' + jd.reports_to,
  '- Interview process: ' + jd.interview_process
].join('\n');

return [{
  json: {
    p: {
      id: req.role_id,
      title: jd.title,
      client_name: req.client_name,
      client_email: req.client_email,
      transcript: req.transcript,
      jd: jd,
      jd_markdown: md,
      search_query: jd.search_query
    }
  }
}];

// Slack approval message for a JD: summary + Approve / Request changes / Reject buttons.
const cfg = $('Config').first().json;
const role = $input.first().json;
const jd = role.jd || {};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const bl = arr => (arr || []).map(x => '• ' + esc(x)).join('\n') || '• Not specified';
const id = String(role.id);

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: cut('📝 JD for approval: ' + role.title, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: cut(
    '*Client:* ' + esc(role.client_name || 'unknown') + '  (candidates see: _' + esc(jd.client_summary_public) + '_)\n' +
    '*Hours:* ' + esc(jd.hours) + '\n*Pay:* ' + esc(jd.rate_band) + '\n*Type:* ' + esc(jd.employment_type) +
    '\n*Start:* ' + esc(jd.start_date), 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: cut('*Must-haves*\n' + bl(jd.must_haves), 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: cut('*Nice-to-haves*\n' + bl(jd.nice_to_haves), 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: cut('*About the role*\n' + esc(jd.about_the_role), 2900) } }
];
if ((jd.open_questions || []).length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: cut('⚠️ *Confirm with the client*\n' + bl(jd.open_questions), 2900) } });
}
if ((jd.internal_notes || []).length) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: cut('🔒 Internal only: ' + jd.internal_notes.map(esc).join(' · '), 2900) }] });
}
blocks.push({
  type: 'actions', block_id: 'jd_actions',
  elements: [
    { type: 'button', style: 'primary', action_id: 'jd_approve', value: id, text: { type: 'plain_text', text: '✅ Approve' } },
    { type: 'button', action_id: 'jd_changes', value: id, text: { type: 'plain_text', text: '✏️ Request changes' } },
    { type: 'button', style: 'danger', action_id: 'jd_reject', value: id, text: { type: 'plain_text', text: '❌ Reject' },
      confirm: { title: { type: 'plain_text', text: 'Reject this JD?' }, text: { type: 'plain_text', text: 'Nothing will be sent to the client.' },
        confirm: { type: 'plain_text', text: 'Reject' }, deny: { type: 'plain_text', text: 'Cancel' } } }
  ]
});
const portal = cfg.portal_url ? ' · <' + cfg.portal_url + '/role.html?id=' + id + '|Full JD in portal>' : '';
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'Role #' + id + ' · version ' + role.version + portal +
  ' · Nothing goes to the client until someone clicks Approve.' }] });

return [{ json: { role_id: role.id, body: { channel: cfg.slack_channel_id, text: '📝 JD for approval: ' + role.title, blocks: blocks } } }];

// Slack returns HTTP 200 even on errors; fail loudly instead of silently.
const r = $input.first().json;
if (!r.ok) throw new Error('Slack API error: ' + (r.error || JSON.stringify(r).slice(0, 200)) +
  (r.error === 'not_in_channel' || r.error === 'channel_not_found' ? ' (invite the bot to the channel: /invite @HG Recruiting Copilot)' : ''));
return [{ json: { channel: r.channel, ts: r.ts } }];

// Transcript was rejected before calling the AI: tell the channel why.
const cfg = $('Config').first().json;
const j = $input.first().json;
return [{ json: { body: { channel: cfg.slack_channel_id, text: '⚠️ Could not write a JD (requested by ' + j.requested_by + '): ' + j.error } } }];
